We say that a relation $\ensuremath{\mathrm L}$ between sets of formulas and formulas in a language $\ensuremath{\mathcal L}$ is a {\em logic} in ${\ensuremath{\mathcal L}}$ when it satisfies the following conditions for each $\Gamma\cup\Delta\cup\{\ensuremath{\varphi}\}\subseteq\ensuremath{\mathit{Fm}_{\!\ensuremath{\mathcal L}}}$:
\begin{flushleft}
\begin{itemize}
\item $\{\ensuremath{\varphi}\}\vdash_\ensuremath{\mathrm L}\ensuremath{\varphi}$. \hfill (Reflexivity)\index{reflexivity}
\item If\/ $\Gamma\vdash_\ensuremath{\mathrm L}\ensuremath{\varphi}$ and $\Gamma \subseteq \Delta$, then $\Delta\vdash_\ensuremath{\mathrm L}\ensuremath{\varphi}$. \hfill (Monotonicity)
\item If\/ $\Delta\vdash_\ensuremath{\mathrm L}\ensuremath{\psi}$ for each $\ensuremath{\psi}\in \Gamma$ and\/ $\Gamma\vdash_\ensuremath{\mathrm L}\ensuremath{\varphi}$, then $\Delta\vdash_\ensuremath{\mathrm L}\ensuremath{\varphi}$. \hfill (Cut)\index{cut}
\item If\/ $\Gamma\vdash_\ensuremath{\mathrm L}\ensuremath{\varphi}$, then $\sigma[\Gamma]\vdash_\ensuremath{\mathrm L}\sigma(\ensuremath{\varphi})$ for each substitution $\sigma$, i.e.\ endomorphisms on ${\ensuremath{\boldsymbol {\mathit{\ensuremath{\mathit{Fm}_{\!\ensuremath{\mathcal L}}}}}}}$. \hfill (Structurality)
\end{itemize}
\end{flushleft}
A logic $\ensuremath{\mathrm L}$ is said to be \emph{finitary} if furthermore
\begin{flushleft}
\begin{itemize}
\item If\/ $\Gamma\vdash_\ensuremath{\mathrm L}\ensuremath{\varphi}$, then there is a \emph{finite} $\Gamma'\subseteq\Gamma$ such that $\Gamma'\vdash_\ensuremath{\mathrm L}\ensuremath{\varphi}$. \hfill (Finitarity)
\end{itemize}
\end{flushleft}
As a matter of convention we say that $\ensuremath{\mathrm L}$ is {\em infinitary} if it is not finitary.

\label{d:expansions}
Let $\ensuremath{\mathcal L_1} \subseteq \ensuremath{\mathcal L_2}$ be two languages and\/ $\ensuremath{\mathrm L_i}$ a logic in $\ensuremath{\mathcal L_i}$ for $i \in \{1,2\}$. We say that $\ensuremath{\mathrm L_2}$ is
\begin{itemize}\addtolength\itemsep{2pt}
\item the {\em expansion of\/ $\ensuremath{\mathrm L_1}$ by a set of consecutions ${\mathcal{S}}$} in $\ensuremath{\mathcal L}_2$ if it is the least logic in $\ensuremath{\mathcal L_2}$ containing $\ensuremath{\mathrm L_1}$ and ${\mathcal{S}}$ (i.e.\
$\ensuremath{\mathrm L_2}$ is axiomatized by all substitutional instances in $\ensuremath{\mathcal L_2}$ of consecutions from ${\mathcal{S}}\cup{\ensuremath{\mathcal{AS}}}$, for any presentation ${\ensuremath{\mathcal{AS}}}$ of\/ $\ensuremath{\mathrm L}_1$). We denote $\ensuremath{\mathrm L_2}$ by $\ensuremath{\mathrm L_1} + {\mathcal{S}}$.

\item an (axiomatic) {\em expansion of\/ $\ensuremath{\mathrm L_1}$} if it is the expansion of\/ $\ensuremath{\mathrm L_1}$ by some set of {\em consecutions} (resp.\ axioms).

\item an {\em extension of\/ $\ensuremath{\mathrm L_1}$} if\/ $\ensuremath{\mathrm L_2}$ is an expansion of\/ $\ensuremath{\mathrm L_1}$ and $\ensuremath{\mathcal L_1}=\ensuremath{\mathcal L_2}$.
\end{itemize}

An \emph{Abelian lattice-ordered group} (\emph{Abelian $\ell$-group}, see e.g.~\cite{Fuchs:PartiallyOrdered}) is a structure of the form $\ensuremath{\langle{A, +, -,\lor,\land,0}\rangle}$ such that:
\begin{itemize}
\item $\ensuremath{\langle{A, +, -, 0}\rangle}$ is an Abelian group, i.e.\ $+$ is a commutative and associative binary operation with unit $0$ and $-$ is the inverse operation (that is, for each $a\in A$, we have $a + (-a) = 0$),
\item $\ensuremath{\langle{A,\lor,\land}\rangle}$ is a lattice, i.e.\ the binary relation $\leq$ defined as $a \leq b$ iff $a \lor b = b$ iff $a \land b = a$ turns out to be an order in which, for each $x,y \in A$, $x \lor y$ and $x\land y$ are respectively the supremum and the infimum of $\{x,y\}$,
\item it satisfies the monotonicity condition, that is, for each $a,b,c\in A$: $a \leq b$ implies $a+c \leq b+c$.
\end{itemize}

\label{l:about nabla-forms}

Let\/ $\ensuremath{\mathrm L}$ be a superabelian logic,  ${\ensuremath{\boldsymbol {\mathit{A}}}}$ an $\ensuremath{\mathrm L}$-algebra, and\/ $\Gamma\cup\{\ensuremath{\varphi}\}$ a set of formulas. If we have $\Gamma \lor \ensuremath{\psi} \vDash_{\ensuremath{\boldsymbol {\mathit{A}}}} \ensuremath{\varphi} \lor \ensuremath{\psi}$ for each $\ensuremath{\psi}$, then we also have $\Gamma \vDash_{\ensuremath{\boldsymbol {\mathit{A}}}} \ensuremath{\varphi}$.
Moreover, if ${\ensuremath{\boldsymbol {\mathit{A}}}} \in \mathbf{Alg}^{\ell}(\ensuremath{\mathrm L})$, the converse implication also holds.

\label{t:strong disjunction}
Let\/ $\ensuremath{\mathrm L}$ be a superabelian logic with a presentation ${\ensuremath{\mathcal{AS}}}$.
Then, the following are equivalent: 
\begin{enumerate}
\item $\lor$ is a strong disjunction. 
\item $R^{\lor}\subseteq \ensuremath{\mathrm L}$ for each consecution $R\in {\ensuremath{\mathcal{AS}}}$.
\item $R^{\lor}\subseteq \ensuremath{\mathrm L}$ for each consecution $R\in \ensuremath{\mathrm L}$.
\end{enumerate}

Let\/ ${{\mathbb K}}$ be a class of $\ensuremath{\mathcal L}$-algebras. We define the following:

\begin{itemize}
    \item $\mathbf{I}({{\mathbb K}})$, $\mathbf{S}({{\mathbb K}})$, $\mathbf{H}({{\mathbb K}})$, $\mathbf{P}({{\mathbb K}})$, $\mathbf{P}_\mathrm{U}({{\mathbb K}})$, and $\ensuremath{\mathbf{P}}_\omega({{\mathbb K}})$ are the classes of all isomorphic images, subalgebras, homomorphic images, direct products, ultraproducts, and countably-filtered products of algebras in ${{\mathbb K}}$, respectively.
    \item ${{\mathbb K}}_{\ensuremath{\mathrm{RFSI}}}$ is the class of relatively finitely subdirectly irreducible members of~${{\mathbb K}}$.
    \item We use ${\ensuremath{\boldsymbol {\mathit{1}}}}$ to denote an arbitrary fixed trivial one-element algebra.
\end{itemize}

\label{t:semilinear completeness}
Let\/ $\ensuremath{\mathrm L}$ be a  superabelian logic and\/ ${{\mathbb K}} \subseteq {\mathbf{Alg}^{*}(\ensuremath{\mathrm L})}$. Then, the following are equivalent:

\begin{enumerate}
	\item $\ensuremath{\mathrm L}$ is strongly complete w.r.t.\ ${{\mathbb K}}$.
    \item ${\mathbf{Alg}^{*}(\ensuremath{\mathrm L})}$ is generated by ${{\mathbb K}}$ as a generalized quasivariety, i.e.\ ${\mathbf{Alg}^{*}(\ensuremath{\mathrm L})} = \ensuremath{\mathbf{ISP}}_\omega({{\mathbb K}})$.
\end{enumerate}

\label{t:semilinear finitary completeness}
Let $\ensuremath{\mathrm L}$ be a superabelian logic and ${{\mathbb K}} \subseteq {\mathbf{Alg}^{*}(\ensuremath{\mathrm L})}$. Then, the following are equivalent:
\begin{enumerate}
\item $\ensuremath{\mathrm L}$ is finitely strongly complete w.r.t.\ ${{\mathbb K}}$.
\item ${\mathbf{Alg}^{*}(\ensuremath{\mathrm L})}$ is generated by ${{\mathbb K}}$ as a quasivariety, i.e.\ ${\mathbf{Alg}^{*}(\ensuremath{\mathrm L})} = \mathbf{ISP}\mathbf{P}_\mathrm{U}({{\mathbb K}})$.
\end{enumerate}
If furthermore $\ensuremath{\mathrm L}$ is finitary and semilinear, then we can add
    \begin{enumerate}\setcounter{enumi}{2}
\item $\mathbf{Alg}^{\ell}(\ensuremath{\mathrm L}) \subseteq \ensuremath{\mathbf{ISP}}_\mathrm{U}({{\mathbb K}},{\ensuremath{\boldsymbol {\mathit{1}}}})$.
\end{enumerate}

\label{c:ultra-decomposition of semilinear logics}
Let\/ $\ensuremath{\mathrm L}$ be a finitary semilinear superabelian logic. Consider finitely many classes of\/ $\ensuremath{\mathrm L}$-algebras ${{\mathbb K}}_1,{{\mathbb K}}_2,\dots, {{\mathbb K}}_n \subseteq {\mathbf{Alg}^{*}(\ensuremath{\mathrm L})}$. Then, the following are equivalent:

\begin{enumerate}
\item $\ensuremath{\mathrm L}$ is finitely strongly complete w.r.t.\ $\bigcup_{i=1}^n {{\mathbb K}}_i$.
\item  $\mathbf{Alg}^{\ell}(\ensuremath{\mathrm L}) \subseteq \mathbf{I}({\ensuremath{\boldsymbol {\mathit{1}}}}) \cup \bigcup_{i \leq n} \ensuremath{\mathbf{ISP}}_\mathrm{U}({{\mathbb K}}_i)$.
\end{enumerate}

Let ${\ensuremath{\boldsymbol {\mathit{A}}}}$ be an Abelian $\ell$-group. Then, the following conditions are equivalent:

\begin{enumerate}
\item ${\ensuremath{\boldsymbol {\mathit{A}}}}$ is Archimedean.
\item \ensuremath{\mathrm{(Arch)}} is valid in ${\ensuremath{\boldsymbol {\mathit{A}}}}$.
\end{enumerate}

Furthermore, if ${\ensuremath{\boldsymbol {\mathit{A}}}}$ is linearly ordered, we can add the following condition:
\begin{enumerate}\setcounter{enumi}{2}	
\item \ensuremath{\mathrm{(Arch)}}$^\lor$ is valid in ${\ensuremath{\boldsymbol {\mathit{A}}}}$.
\end{enumerate}

\label{l:strongly,strictly-decreasing}
Let ${\ensuremath{\langle{a_i}\rangle}}_{i \in \ensuremath{\mathbb{N}}}$ be a non-trivial sequence of elements of an Abelian $\ell$-group ${\ensuremath{\boldsymbol {\mathit{A}}}}$. If ${\ensuremath{\langle{a_i}\rangle}}_{i \in \ensuremath{\mathbb{N}}}$ is strongly decreasing, then it is strictly decreasing. 
If ${\ensuremath{\boldsymbol {\mathit{A}}}}$ is an Archimedean chain and it has a strictly decreasing sequence of positive elements, then it also has a non-trivial strongly decreasing sequence.

\label{t:pAb lots R}
Let ${\ensuremath{\boldsymbol {\mathit{A}}}}$ be a non-trivial Abelian $\ell$-group.
${\ensuremath{\ensuremath{\mathrm {pAb}}}}$ is finitely strongly complete w.r.t.\ $\ensuremath{\mathbf{p}} {\ensuremath{\boldsymbol {\mathit{A}}}}=\{{\ensuremath{\boldsymbol {\mathit{A}}}}_a\mid a \in {\ensuremath{\boldsymbol {\mathit{A}}}}\}$.

\emph{\L ukasiewicz unbound logic} $\ensuremath{\ensuremath{\mathrm {Lu}}}$ is the extension of the logic ${\ensuremath{\ensuremath{\mathrm {pAb}}}}$ by the rule:
\begin{equation*}\tag{Lu}
   \ensuremath{\mathtt{f}} \lor \ensuremath{\varphi} \mathrel{\blacktriangleright} \ensuremath{\varphi}
\end{equation*}

\label{l:similar extensions}
Let ${\ensuremath{\boldsymbol {\mathit{A}}}} \in {\mathbf{Alg}^{*}(\ensuremath{\mathrm {\ensuremath{\ensuremath{\mathrm {pAb}}}}})}$ and ${\ensuremath{\boldsymbol {\mathit{A}}}} \neq {\ensuremath{\boldsymbol {\mathit{1}}}}$. Then, the following conditions are equivalent:
\begin{enumerate}
\item $\ensuremath{\mathtt{f}}^{\ensuremath{\boldsymbol {\mathit{A}}}} \not\geq 0$.
\item The rule $\ensuremath{\mathtt{f}} \mathrel{\blacktriangleright} \ensuremath{\varphi}$ is valid in ${\ensuremath{\boldsymbol {\mathit{A}}}}$.
\end{enumerate}

Furthermore, if ${\ensuremath{\boldsymbol {\mathit{A}}}}$ is linearly ordered, we can add the following condition:
\begin{enumerate}\setcounter{enumi}{2}	
\item The rule $\ensuremath{\mathtt{f}} \lor \ensuremath{\varphi} \mathrel{\blacktriangleright} \ensuremath{\varphi}$ is valid in ${\ensuremath{\boldsymbol {\mathit{A}}}}$.
\end{enumerate}

\label{t:tau}
Let us consider the mapping $\tau\colon\ensuremath{\mathit{Fm}_{\!\ensuremath{\mathcal \ensuremath{\mathcal L_{\ensuremath{\ensuremath{\mathrm {pAb}}}}}}}} \longrightarrow \ensuremath{\mathit{Fm}_{\!\ensuremath{\mathcal \ensuremath{\mathcal L_{\ensuremath{\ensuremath{\mathrm {pAb}}}}}}}}$ defined recursively as follows:
\begin{itemize}
\item $\tau\colon \ensuremath{\mathtt{f}} \mapsto -\ensuremath{\mathtt{f}}$.
\item $\tau\colon \ensuremath{\mathtt{t}} \mapsto \ensuremath{\mathtt{t}}$.
\item $\tau\colon x \mapsto x $ for each variable $x$.
\item $\tau\colon (\ensuremath{\psi} \circ \xi) \mapsto (\tau(\ensuremath{\psi}) \circ \tau(\xi))$ for all binary connectives $\circ \in \ensuremath{\mathcal L_{\ensuremath{\ensuremath{\mathrm {pAb}}}}}$.
\end{itemize}
For any consecution $\Gamma \mathrel{\blacktriangleright} \ensuremath{\varphi}$ and for each Abelian $\ell$-group ${\ensuremath{\boldsymbol {\mathit{A}}}}$, and $a \in A$ we have

$$\Gamma\vDash_{{\ensuremath{\boldsymbol {\mathit{A}}}}_a} \ensuremath{\varphi} \qquad \text{iff} \qquad \tau[\Gamma]\vDash_{{\ensuremath{\boldsymbol {\mathit{A}}}}_{-a}} \tau(\ensuremath{\varphi}).$$


In particular, for any consecution $\Gamma \mathrel{\blacktriangleright} \ensuremath{\varphi}$ we have
\begin{enumerate}    
\item $\Gamma\vdash_{\ensuremath{\ensuremath{\mathrm {Lu}}}} \ensuremath{\varphi}$ iff $\tau[\Gamma]\vdash_{\ensuremath{\ensuremath{\mathrm {Lu}}}^*} \tau(\ensuremath{\varphi}) $.
\item $\Gamma\vdash_{\ensuremath{\ensuremath{\mathrm {Lu}}}^*} \ensuremath{\varphi}$ iff $\tau[\Gamma]\vdash_{\ensuremath{\ensuremath{\mathrm {Lu}}}} \tau(\ensuremath{\varphi}) $.
\end{enumerate}
